package android.os;public class ParcelFileDescriptor implements java.io.Closeable{public final int id;public boolean closed;private final java.io.FileDescriptor fd=new java.io.FileDescriptor();public ParcelFileDescriptor(int n){id=n;}public static ParcelFileDescriptor adoptFd(int fd){return new ParcelFileDescriptor(fd);}public java.io.FileDescriptor getFileDescriptor(){if(closed)throw new IllegalStateException();return fd;}public void close()throws java.io.IOException{closed=true;}}